  --secondary: rgb(31, 27, 78);
  --secondary-foreground: rgb(225, 231, 253);
  --muted: rgb(31, 27, 78);
  --muted-foreground: rgb(196, 181, 252);
  --accent: rgb(68, 59, 201);
  --accent-foreground: rgb(225, 231, 253);
  --destructive: rgb(241, 68, 68);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(46, 12, 102);
  --input: rgb(46, 12, 102);
  --ring: rgb(140, 93, 248);
  --chart-1: rgb(167, 139, 251);
  --chart-2: rgb(140, 93, 248);
  --chart-3: rgb(124, 56, 238);
  --chart-4: rgb(109, 41, 216);
  --chart-5: rgb(90, 32, 181);
  --radius: 0.625rem;
  --sidebar: rgb(15, 24, 43);
